class TestConfiguration():
    driver = None

    @pytest.fixture(autouse=True, scope="class")
    def _inject_config(self, request, test_config):
        cls = request.cls
        # 將 conftest.py 的設備配置給 cls 類別物件
        for key, value in vars(test_config).items():
            setattr(cls, key, value)

    @classmethod
    def setup_class(cls):
        """
        整個測試類別開始時，只會執行一次
        """
        print("\n正在啟動瀏覽器並登入 EMS...")
        match browser:
            case "chrome":
                options = webdriver.ChromeOptions()
                options.add_argument('ignore-certificate-errors')
                prefs = {
                    "download.default_directory": downloadpath,
                    "download.prompt_for_download": False,
                    "download.directory_upgrade": True
                }
                options.add_experimental_option("prefs", prefs)
                cls.driver = webdriver.Chrome(options)
            case "edge":
                options = webdriver.EdgeOptions()
                options.add_argument('ignore-certificate-errors')
                prefs = {
                    "download.default_directory": downloadpath,
                    "download.prompt_for_download": False,
                    "download.directory_upgrade": True
                }
                options.add_experimental_option("prefs", prefs)
                cls.driver = webdriver.Edge(options)
            case "firefox":
                options = webdriver.FirefoxOptions()
                options.add_argument('-ignore-certificate-errors')
                options.set_preference("browser.download.folderList", 2)
                options.set_preference("browser.download.dir", downloadpath)
                cls.driver = webdriver.Firefox(options)       
        cls.driver.implicitly_wait(waitTime)
        cls.driver.maximize_window()
        cls.driver.get(emsURL)
        # 執行登入 (只登入這一次)
        # 傳入 cls 而非 self，因為這是在 classmethod 裡
        loginEMS(cls, emsUsr, emsPwd)
        time.sleep(3)

    @classmethod
    def teardown_class(cls):
        """
        整個類別所有測試案例執行完畢後，關閉瀏覽器
        """
        if cls.driver:
            print("\n所有測試執行完畢，關閉瀏覽器。")
            cls.driver.quit()

