    async def test_EMS1_6088_ACL_AntiMACSpoof(self):
        # OLT140X not support
        if "OLT" in dutType : return
        enterConigFunPage (self, dutNodeName, "ACL", "Anti MAC Spoof")
        # Apply without select port
        self.driver.find_element(By.XPATH, "//*[@id=\'sw_ouifilter\']//input[@value=\'Apply\']").click()
        time.sleep(1)
        with assume: assert self.driver.find_element(By.ID, "message_text").text == 'Please select slot and port.'
        self.driver.find_element(By.CSS_SELECTOR, "#message_diag .button").click()
        time.sleep(1)
        # NXA, NXC, MSC, GLC, OLC3416-42 support
        supportCardTypeList = ["NXC400", "NXA340", "MSC1240QA", "MSC1240QB", "MSC1240XA", "MSC1280XA", "MSC1280XB"
                               , "GLC1440X-55", "GLC1440X-55A", "GLC1540X-55A", "OLC3416-42", "OLC3416-42A"]
        invalidCardIDList = ["0", "--"]
        for ind, cardType in enumerate(cardTypeName):
            if (dutAllCardID[ind] in invalidCardIDList) or (cardType not in supportCardTypeList):
                continue
            slotID = dutAllCardID[ind]
            slotName = (slotID + " - " +  cardType)
            portId = dutAllCardPortID[ind]
            cliPortType = cliPortTypeDic[cardPortTypeName[ind]]
            cliPortAid = portId if "NXC" in cardType else slotID + "-" + portId
            Select(self.driver.find_element(By.ID, "sw_ouifilter_slot_combobox")).select_by_visible_text(slotName)
            Select(self.driver.find_element(By.ID, "sw_ouifilter_port_combobox")).select_by_visible_text(portId)
            # Check default value
            with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_macspoof_select").get_attribute("value") == "1"
            if ("NXA" in cardType) or ("OLC" in cardType):
                with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select").get_attribute("value") == "1"
            else: 
                with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select").get_attribute("value") == "2"
            # Set
            Select(self.driver.find_element(By.ID, "acl_antimacspoof_macspoof_select")).select_by_visible_text("Disable")
            if ("NXA" in cardType) or ("OLC" in cardType):
                Select(self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select")).select_by_visible_text("Disable")
            self.driver.find_element(By.XPATH, "//*[@id=\'sw_ouifilter\']//input[@value=\'Apply\']").click()
            time.sleep(3)
            self.driver.find_element(By.CSS_SELECTOR, "#message_diag .button").click()
            time.sleep(3)
            # Check set value in EMS and CLI
            cliReturnList = await cliCommandList (dutIp, dutAdminName, dutAdminPwd, ["show running-config interface " + cliPortType + " " + cliPortAid +" fdb"])
            with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_macspoof_select").get_attribute("value") == "2"
            with assume: assert "fdb anti-spoofing disable" in cliReturnList
            if ("NXA" in cardType) or ("OLC" in cardType):
                with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select").get_attribute("value") == "2"
                with assume: assert "fdb spoofing-action disable" in cliReturnList
            else: 
                with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select").get_attribute("value") == "2"
            # Switch other page then check set value again
            enterConigFunPage (self, dutNodeName, "System", "General Setup")
            enterConigFunPage (self, dutNodeName, "ACL", "Anti MAC Spoof")
            Select(self.driver.find_element(By.ID, "sw_ouifilter_slot_combobox")).select_by_visible_text(slotName)
            Select(self.driver.find_element(By.ID, "sw_ouifilter_port_combobox")).select_by_visible_text(portId)
            time.sleep(3)
            with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_macspoof_select").get_attribute("value") == "2"
            if ("NXA" in cardType) or ("OLC" in cardType):
                with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select").get_attribute("value") == "2"
            else: 
                with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select").get_attribute("value") == "2"
            # Back to default value
            Select(self.driver.find_element(By.ID, "acl_antimacspoof_macspoof_select")).select_by_visible_text("Enable")
            if ("NXA" in cardType) or ("OLC" in cardType):
                Select(self.driver.find_element(By.ID, "acl_antimacspoof_spoof_select")).select_by_visible_text("Enable")
            self.driver.find_element(By.XPATH, "//*[@id=\'sw_ouifilter\']//input[@value=\'Apply\']").click()
            time.sleep(3)
            self.driver.find_element(By.CSS_SELECTOR, "#message_diag .button").click()
            time.sleep(3)
            # Check set value in EMS and CLI
            cliReturnList = await cliCommandList (dutIp, dutAdminName, dutAdminPwd, ["show running-config interface " + cliPortType + " " + cliPortAid +" fdb"])
            with assume: assert self.driver.find_element(By.ID, "acl_antimacspoof_macspoof_select").get_attribute("value") == "1"
